30	/**
31	 * 주문 배송 관련 비즈니스 로직을 처리하는 서비스
32	 */
33	@Slf4j
34	@Service
35	@RequiredArgsConstructor
36	public class OrderShipmentCommandService {
37	
38	    private final OrderShipmentRepository orderShipmentRepository;
39	    private final NotificationCommandService notificationCommandService;
40	    private final SaleBidQueryService saleBidQueryService;
41	    private final OrderBidQueryService orderBidQueryService;
