   171	    @Enumerated(EnumType.STRING)
   172	    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)
   173	
   174	    @OneToOne(fetch = FetchType.LAZY)
   175	    @JoinColumn(name = "order_id")
   176	    private Order order; // 매칭된 구매 엔티티
   177	
   178	    @OneToOne(fetch = FetchType.LAZY)
   179	    @JoinColumn(name = "sale_id")
   180	    private Sale sale; // 매칭된 판매 엔티티
   181	
   182	    // 즉시 구매 플래그
