   152	@AllArgsConstructor
   153	@Builder
   154	public class OrderBid extends BaseTimeEntity {
   155	
   156	    @Id
   157	    @GeneratedValue(strategy = GenerationType.IDENTITY)
   158	    private Long id;
   159	
   160	    @ManyToOne(fetch = FetchType.LAZY)
   161	    @JoinColumn(name = "user_id")
   162	    private User user; // 구매자 정보
   163	
   164	    @ManyToOne(fetch = FetchType.LAZY)
   165	    @JoinColumn(name = "product_size_id")
   166	    private ProductSize productSize; // 구매 대상 상품 사이즈
   167	
   168	    private int bidPrice; // 입찰 가격
   169	
   170	    @Builder.Default
   171	    @Enumerated(EnumType.STRING)
   172	    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)
   173	
   174	    @OneToOne(fetch = FetchType.LAZY)
   175	    @JoinColumn(name = "order_id")
   176	    private Order order; // 매칭된 구매 엔티티
   177	
   178	    @OneToOne(fetch = FetchType.LAZY)
   179	    @JoinColumn(name = "sale_id")
   180	    private Sale sale; // 매칭된 판매 엔티티
   181	
   182	    // 즉시 구매 플래그
   183	    @Builder.Default
   184	    @Column(nullable = false)
   185	    private boolean isInstantPurchase = false;
   186	
   187	    /**
   188	     * Order와의 양방향 관계를 설정합니다.
   189	     * 기존 관계가 있다면 해제하고 새 관계를 설정합니다.
   190	     *
   191	     * @param order 연결할 Order 객체
   192	     */
   193	    public void assignOrder(Order order) {
   194	        // 기존 관계가 있으면 해제
   195	        if (this.order != null && this.order != order) {
   196	            Order oldOrder = this.order;
   197	            this.order = null;
   198	            if (oldOrder.getOrderBid() == this) {
   199	                oldOrder.assignOrderBid(null);
   200	            }
   201	        }
   202	
   203	        // 새 관계 설정
   204	        this.order = order;
   205	
   206	        // 매칭 상태로 변경
   207	        if (order != null) {
   208	            this.status = BidStatus.MATCHED;
   209	
   210	            // Order 쪽에도 관계 설정
   211	            if (order.getOrderBid() != this) {
   212	                order.assignOrderBid(this);
   213	            }
   214	        }
   215	    }
   216	
   217	    /**
   218	     * Sale과의 양방향 관계를 설정합니다.
   219	     *
   220	     * @param sale 연결할 Sale 객체
   221	     */
   222	    public void assignSale(Sale sale) {
   223	        this.sale = sale;
   224	        this.status = BidStatus.MATCHED;
   225	    }
   226	
   227	    /**
   228	     * 즉시 구매로 표시합니다.
   229	     */
   230	    public void markAsInstantPurchase() {
   231	        this.isInstantPurchase = true;
   232	    }
   233	
   234	    /**
   235	     * 입찰 상태를 업데이트합니다.
   236	     *
   237	     * @param newStatus 새 입찰 상태
   238	     */
   239	    public void updateStatus(BidStatus newStatus) {
   240	        this.status = newStatus;
   241	    }
   242	}

